 if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)$error='فایل CSV انتخاب نشده یا قابل دریافت نیست.';
 else{$ext=strtolower(pathinfo($_FILES['csv']['name'],PATHINFO_EXTENSION));$max=(int)app_config()['security']['upload_max_mb']*1024*1024;
  if($ext!=='csv'||(int)$_FILES['csv']['size']>$max)$error='فقط فایل CSV تا حجم مجاز قابل بارگذاری است.';
  else{try{$rows=$importer->rows($_FILES['csv']['tmp_name']);$row=$rows->current();if(!$row)throw new RuntimeException('فایل داده‌ای ندارد.');$safe=bin2hex(random_bytes(16)).'.csv';$dir=dirname(__DIR__).'/storage/uploads';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('مسیر ذخیره فایل قابل ایجاد نیست.');if(!move_uploaded_file($_FILES['csv']['tmp_name'],$dir.'/'.$safe))throw new RuntimeException('ذخیره امن فایل ناموفق بود.');$data=$row;$data['_source_file']=basename($_FILES['csv']['name']);$data['_source_path']=$safe;$_SESSION['_asset_import']=$data;audit('hardware_csv_preview','asset',null,['file'=>$data['_source_file']]);}catch(Throwable $e){$error=$e->getMessage();}}
