  $technical=$_POST['technical']??[];foreach($technical as $k=>$v)$technical[$k]=is_array($v)?$v:trim((string)$v);$sourcePath=(string)($_POST['_source_path']??'');$sourceName=(string)($_POST['_source_file']??'');
  $st=db()->prepare('INSERT INTO assets(asset_no,asset_type,device_subtype,hostname,personnel_id,location,department,manufacturer,model,serial_no,technical,status,source_file,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
  $st->execute([$assetNo,$_POST['asset_type'],trim((string)($_POST['device_subtype']??'')),trim((string)($_POST['hostname']??'')),($_POST['personnel_id']??'')!==''?(int)$_POST['personnel_id']:null,trim((string)($_POST['location']??'')),trim((string)($_POST['department']??'')),trim((string)($_POST['manufacturer']??'')),trim((string)($_POST['model']??'')),trim((string)($_POST['serial_no']??'')),json_encode($technical,JSON_UNESCAPED_UNICODE),$_POST['status']??'active',$sourcePath?:$sourceName,user()['id'],user()['id']]);
  foreach($importer->disks($data) as $d){$q=db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)');$q->execute([$assetNo,$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);}
  foreach($importer->ramSlots($data) as $r){$q=db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$assetNo,$r['slot_no'],$r['state']??'unknown',$r['capacity_gb']??null,$r['ram_type']??null,$r['speed_mhz']??null,$r['manufacturer']??null,$r['part_number']??null,$r['serial_no']??null]);}
  unset($_SESSION['_asset_import']);audit('asset_created','asset',$assetNo,['type'=>$_POST['asset_type'],'source'=>$sourceName]);flash('success','تجهیز با موفقیت ثبت شد.');redirect('asset_view.php?asset_no='.urlencode($assetNo));
 }
}
